package com.pms.hotelboutique.backend.modules.guestauth.infrastructure.security;
import com.pms.hotelboutique.backend.modules.guestauth.application.*; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.List; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class GuestJwtAuthenticationFilter extends OncePerRequestFilter {
 private final GuestJwtService jwt; private final GuestAuthService auth; public GuestJwtAuthenticationFilter(GuestJwtService jwt,GuestAuthService auth){this.jwt=jwt;this.auth=auth;}
 @Override protected boolean shouldNotFilter(HttpServletRequest request){return !request.getRequestURI().startsWith("/api/v1/guest-auth/");}
 @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String header=request.getHeader(HttpHeaders.AUTHORIZATION);if(header==null||!header.startsWith("Bearer ")){chain.doFilter(request,response);return;}try{GuestPrincipal principal=auth.getActivePrincipal(jwt.parse(header.substring(7)));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(principal,null,List.of(new SimpleGrantedAuthority("ROLE_GUEST"))));chain.doFilter(request,response);}catch(JwtException|GuestAuthenticationException|IllegalArgumentException ex){SecurityContextHolder.clearContext();response.sendError(HttpServletResponse.SC_UNAUTHORIZED);}}
}
